<script setup lang="ts">
import {ref,computed,onMounted} from 'vue'
import {ArrowLeft,BookOpen,NotebookPen,Flame,Clock3} from 'lucide-vue-next'
import {api} from '../api'
import type {ReadingStats} from '../api/types'
import {useRequestScope} from '../platform/request-scope'
import {useApp} from '../stores/app'
const store=useApp(),capture=useRequestScope(),stats=ref<ReadingStats|null>(null),goal=ref(20),error=ref(''),busy=ref(false)
let generation=0
const weekSeconds=computed(()=>stats.value?.week.reduce((total,day)=>total+day.seconds,0)||0)
const chartMax=computed(()=>Math.max(60,...(stats.value?.week.map(day=>day.seconds)||[])))
const minutes=(seconds:number)=>Number((seconds/60).toFixed(1)).toLocaleString('zh-CN')
async function load(){const scope=capture(),request=++generation;try{const data=await api<ReadingStats>('/reading-stats?offsetMinutes='+(-new Date().getTimezoneOffset()),{cache:true});if(scope.valid()&&request===generation){stats.value=data;goal.value=data.goalMinutes;error.value=''}}catch(e){if(scope.valid()&&request===generation)error.value=(e as Error).message}}
async function saveGoal(){if(!stats.value||busy.value)return;const scope=capture();busy.value=true;try{await api('/reading-goal',{method:'PUT',body:{expectedVersion:stats.value.goalVersion,minutes:goal.value}});if(scope.valid()){store.message('每日阅读目标已更新');await load()}}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())busy.value=false}}
onMounted(load)
</script>
<template><RouterLink to="/library" class="inline-link"><ArrowLeft :size="18"/>返回书架</RouterLink><div class="page-heading" style="margin-top:24px"><span class="eyebrow">一点时间 · 一点积累</span><h1>你的阅读记录</h1><p>不必赶路，每一天都可以多读一小会儿。</p></div><p v-if="error" class="error" role="alert">{{error}}<button @click="load">重新加载</button></p><div v-if="!stats&&!error" class="loading">正在整理阅读轨迹…</div><template v-if="stats"><section class="insight-summary"><article class="insight-main"><span class="eyebrow"><Clock3 :size="16"/>今天读了</span><p class="reading-number">{{minutes(stats.todaySeconds)}}<span>分钟</span></p><progress :value="Math.min(stats.todaySeconds,stats.goalMinutes*60)" :max="stats.goalMinutes*60" aria-label="今日阅读目标进度"/><p class="muted">{{stats.todaySeconds>=stats.goalMinutes*60?'今天的阅读目标已完成。':'距离每日 '+stats.goalMinutes+' 分钟目标，还可以再读一会儿。'}}</p></article><div class="insight-facts"><article><Flame :size="20"/><strong>{{stats.streakDays}}<small>天</small></strong><span>连续阅读</span></article><article><BookOpen :size="20"/><strong>{{stats.bookCount}}<small>本</small></strong><span>私人藏书</span></article><article><NotebookPen :size="20"/><strong>{{stats.noteCount}}<small>条</small></strong><span>阅读笔记</span></article></div></section><section class="week-card"><div class="row between"><div><span class="eyebrow">最近七天</span><h2>阅读慢慢积累</h2></div><p class="muted">共 {{minutes(weekSeconds)}} 分钟</p></div><div class="week-chart" role="list" aria-label="近七天阅读时长"><div v-for="day in stats.week" :key="day.date" role="listitem" :aria-label="day.date+' 阅读 '+minutes(day.seconds)+' 分钟'" class="week-day"><small>{{minutes(day.seconds)}}</small><div class="bar-track"><span :class="{today:day.date===stats.week.at(-1)?.date}" :style="{height:Math.max(day.seconds?4:0,day.seconds/chartMax*100)+'%'}"/></div><span>{{day.date.slice(5).replace('-','/')}}</span></div></div><p v-if="weekSeconds===0" class="muted">打开一本书，第一段阅读时间会在这里留下记录。</p></section><section class="goal-card"><div><span class="eyebrow">给自己一点阅读时间</span><h2>每日阅读目标</h2><p class="muted">累计阅读 {{minutes(stats.totalSeconds)}} 分钟。时长按前台阅读记录，切到后台、离线或长时间未操作时暂停。</p></div><form @submit.prevent="saveGoal"><label>每天读多少分钟？<input v-model.number="goal" type="number" min="5" max="240" required></label><button class="primary" :disabled="busy||!store.online">{{busy?'正在保存…':'保存目标'}}</button></form></section></template></template>
